from pathlib import Path
p=Path(__file__).resolve().parents[1]
css='''*{box-sizing:border-box}body{margin:0;background:#f4f3ee;color:#182b34;font:16px/1.75 system-ui,sans-serif}header,main,footer{max-width:1080px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d2d9d5}a{color:#246353}small,.muted{color:#566770}.eyebrow{font-size:12px;letter-spacing:2px;color:#246353;text-transform:uppercase}h1{font-size:clamp(28px,5vw,48px);line-height:1.2;margin:15px 0}h2{font-size:21px}p{max-width:800px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.card{background:#fff;border:1px solid #d2d9d5;border-radius:14px;padding:24px;margin:20px 0}.tag{display:inline-block;padding:2px 9px;border-radius:20px;background:#e3eee7;font-size:12px}input,textarea,select{display:block;width:100%;border:1px solid #a8b8b2;border-radius:8px;padding:12px;font:inherit;color:inherit;background:#fff}textarea{min-height:105px}label{display:block;margin:12px 0 5px;font-weight:600}button{cursor:pointer;border:1px solid #246353;background:#246353;color:white;border-radius:8px;padding:11px 18px;font:inherit;margin:8px 0}button.secondary{background:white;color:#246353}button:hover{filter:brightness(.9)}button:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #bd7027;outline-offset:3px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats div{background:#edf2ef;border-radius:9px;padding:12px;flex:1}.stats strong{font-size:27px;display:block}.notice{padding:13px;border-inline-start:4px solid #bd7027;background:#fff6e8}.result{border-top:1px solid #d2d9d5;padding:12px 0}.result strong{display:block}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;border-bottom:1px solid #d2d9d5;text-align:start}.scroll{overflow:auto}pre{white-space:pre-wrap;word-break:break-word;font-size:13px;background:#edf2ef;padding:15px}footer{font-size:13px;border-top:1px solid #d2d9d5}details{margin:15px 0}summary{cursor:pointer;font-weight:600}@media(max-width:700px){.grid{grid-template-columns:1fr}header,main,footer{padding:18px}.card{padding:18px}.stats strong{font-size:23px}}'''
head=lambda title:f'<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}</style><header><b>Deema Alrafi <span class="tag">Experimental · v0.1</span></b><a href="https://github.com/cometeux/arabic-ai-quality-lab" target="_blank" rel="noopener">الكود والتوثيق ↗</a></header><main>'
foot='</main><footer>مشروع تجريبي جديد · صُمم ونُفذ بمساعدة أدوات برمجة بالذكاء الاصطناعي. لا توجد نماذج مدربة أو نتائج إنتاجية مزعومة. <a href="https://huggingface.co/Deema9">Deema9</a></footer></html>'
common='''function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}'''
retrieval='''<div class="eyebrow" dir="ltr">01 / Arabic retrieval lab</div><h1>هل يجد البحث العربي<br>المصدر الصحيح؟</h1><p>قارني بحث BM25 حرفيًّا مع نفس المحرك بعد معالجة الهمزات والتشكيل والتطويل والألف المقصورة. افحصي المصدر والنتيجة بدل الاكتفاء بانطباع أن البحث «ذكي».</p><div class="notice">هذه تجربة بحث نصي، وليست RAG كاملًا أو نموذج إجابة. العثور على كلمات متشابهة لا يثبت أن المصدر يدعم الادعاء.</div><section class="card"><label for="query">سؤال أو كلمات بحث</label><input id="query" value="اجازة" maxlength="2000"><button id="search">مقارنة النتائج</button> <button class="secondary" id="example">مثال على نتيجة لا تثبت الادعاء</button><div class="grid"><section><h2>قبل التطبيع · Baseline</h2><div id="before" aria-live="polite"></div></section><section><h2>بعد التطبيع · Normalized</h2><div id="after" aria-live="polite"></div></section></div></section><section class="card"><h2>قياس قابل لإعادة التشغيل</h2><p>12 وثيقة و30 حالة اصطناعية: 26 حالة استرجاع و4 حالات بلا دعم في الوثائق. الملصقات مكتوبة لهذه التجربة وغير مراجعة مستقلًا. لا توجد مجموعة اختبار محجوبة.</p><label for="category">مجموعة الحالات</label><select id="category"><option value="all">كل الحالات</option><option value="alef">اختلاف الهمزات</option><option value="exact">كلمات مطابقة</option><option value="multi_term">عدة كلمات</option><option value="unsupported_claim">ادعاء غير مدعوم</option><option value="out_of_scope">خارج النطاق</option><option value="diacritics">التشكيل</option><option value="tatweel">التطويل</option></select><div class="grid"><div id="metricsBefore"></div><div id="metricsAfter"></div></div><div class="scroll"><table><thead><tr><th>الحالة</th><th>السؤال</th><th>الدعم المتوقع</th><th>أول 3 قبل</th><th>أول 3 بعد</th></tr></thead><tbody id="rows"></tbody></table></div><button class="secondary" id="export">تنزيل تقرير JSON</button><details><summary>كيف أقرأ الأرقام؟</summary><p>Hit@3 = نسبة الحالات المدعومة التي يظهر مصدرها ضمن أول ثلاث نتائج. MRR = متوسط مقلوب ترتيب أول مصدر صحيح. حالات عدم الدعم تُعرض منفصلة. الدرجة ليست احتمال صحة، ولا توجد عتبة امتناع مُعايرة. التطبيع قد يدمج كلمات مختلفة ولا يعالج المرادفات أو اللهجات أو الأخطاء الإملائية.</p></details></section><section class="card"><h2>مصادر التجربة</h2><div id="docs"></div></section>'''
rjs='''const f=window.FIXTURES;function show(target,results){target.replaceChildren();if(!results.length){target.append(el('p','لا توجد كلمات مشتركة. هذه ليست آلية للتحقق من صحة الإجابة.'));return}for(const r of results.slice(0,3)){const d=el('div',undefined,'result');d.append(el('strong',r.title+' · '+r.id),el('p',r.text),el('small','BM25: '+r.score.toFixed(3)+' | الكلمات المشتركة: '+r.terms.join('، ')));target.append(d)}}function search(){show(document.getElementById('before'),Retrieval.rank(document.getElementById('query').value,f.documents,false));show(document.getElementById('after'),Retrieval.rank(document.getElementById('query').value,f.documents,true))}let report;function metrics(id,title,r){const e=document.getElementById(id);e.replaceChildren(el('h2',title));e.append(el('p',`Hit@3: ${r.hitAtK===null?'—':(r.hitAtK*100).toFixed(1)+'%'} · MRR: ${r.mrr===null?'—':r.mrr.toFixed(3)}`),el('p',`${r.answerable} حالات مدعومة · ${r.unanswerableWithResults}/${r.unanswerable} حالات بلا دعم أعادت نتائج`));}function evaluate(){const cat=document.getElementById('category').value;const cases=f.cases.filter(c=>cat==='all'||c.category===cat);const a=Retrieval.evaluate(f.documents,cases,false),b=Retrieval.evaluate(f.documents,cases,true);report={fixtureVersion:f.version,category:cat,limitations:f.provenance,baseline:a,normalized:b};metrics('metricsBefore','قبل التطبيع',a);metrics('metricsAfter','بعد التطبيع',b);const body=document.getElementById('rows');body.replaceChildren();cases.forEach((c,i)=>{const tr=el('tr');[c.id,c.query,c.relevant_ids.join(', ')||'لا يوجد دعم',a.rows[i].top_ids.join(', ')||'—',b.rows[i].top_ids.join(', ')||'—'].forEach(t=>tr.append(el('td',t)));body.append(tr)})}document.getElementById('search').onclick=search;document.getElementById('query').onkeydown=e=>{if(e.key==='Enter')search()};document.getElementById('example').onclick=()=>{document.getElementById('query').value='العمل عن بعد متاح خمسة أيام';search()};document.getElementById('category').onchange=evaluate;document.getElementById('export').onclick=()=>download('retrieval-report.json',report);f.documents.forEach(d=>document.getElementById('docs').append(el('p',d.id+' · '+d.text)));search();evaluate();'''
(p/'retrieval/index.html').write_text(head('Arabic Retrieval Lab — Deema Alrafi')+retrieval+'<script>'+common+(p/'retrieval/engine.js').read_text()+(p/'retrieval/data.js').read_text()+rjs+'</script>'+foot)
actions='''<div class="eyebrow" dir="ltr">02 / Action review</div><h1>من قرار اجتماع<br>إلى تكليف قابل للمتابعة.</h1><p>افحصي اكتمال التكليف قبل إضافته لقائمة المهام. الأداة تسأل عن المسؤول والموعد وتلفت الانتباه إلى الصياغة الواسعة؛ لا تختلق معلومات ناقصة.</p><div class="notice">فحص قواعد استرشادي يعمل محليًا في المتصفح. اجتياز القواعد لا يثبت جودة التكليف. لا يقرأ التسجيلات ولا يستخرج المهام بنموذج لغوي.</div><div class="grid"><section class="card"><h2>مسودة التكليف</h2><label for="task">ما المطلوب تسليمه؟</label><textarea id="task" maxlength="10000">تحسين تجربة الخدمة غدا</textarea><label for="owner">المسؤول عن التسليم</label><input id="owner" maxlength="200" placeholder="اسم أو دور — أدخليه بعد الاتفاق"><label for="due">تاريخ التسليم</label><input id="due" type="date"><label for="today">تاريخ المراجعة</label><input id="today" type="date"><button id="review">فحص التكليف</button> <button class="secondary" id="example">مثال مكتمل</button></section><section class="card"><h2>ما الذي يحتاج مراجعة؟</h2><div id="summary" aria-live="polite"></div><div id="issues"></div><h2>السجل المنظم</h2><pre id="record" dir="ltr"></pre><button class="secondary" id="export">تنزيل السجل والملاحظات</button></section></div><section class="card"><h2>لماذا هذه القواعد؟</h2><table><thead><tr><th>الفحص</th><th>قرار التجربة</th><th>الحد</th></tr></thead><tbody><tr><td>المسؤول والموعد</td><td>إدخال صريح بدل استنتاج شخص أو تاريخ</td><td>لا يتحقق من قبول المسؤول</td></tr><tr><td>تحسين / متابعة</td><td>تنبيه لطلب مخرج يمكن قياسه</td><td>قد تكون العبارة مناسبة في سياقها</td></tr><tr><td>غدا / قريبًا</td><td>طلب تاريخ مطلق</td><td>لا يحول التاريخ تلقائيا</td></tr><tr><td>عدة تكليفات</td><td>تنبيه عند الفاصلة المنقوطة أو أسطر متعددة</td><td>قد يفوّت بعض التكليفات أو يعطي تنبيهًا زائدًا</td></tr></tbody></table><p>النص المدخل لا يرسل إلى خادم من كود الأداة. لا يوجد حفظ دائم؛ تنزيل JSON اختياري. منصة الاستضافة نفسها قد تجمع بيانات الاستخدام المعتادة.</p></section>'''
ajs='''const $=id=>document.getElementById(id);$('today').value=new Date().toLocaleDateString('en-CA');let report;function run(){report=Actions.review({task:$('task').value,owner:$('owner').value,due:$('due').value,today:$('today').value});$('summary').replaceChildren(el('p',report.issues.length?`${report.required} حقول مطلوبة · ${report.review} تنبيهات للمراجعة`:'لا توجد ملاحظات ضمن القواعد الحالية. راجعي المعنى وقبول المسؤول قبل الاعتماد.'));$('issues').replaceChildren();report.issues.forEach(i=>{const d=el('div',undefined,'result');d.append(el('span',i.severity==='required'?'حقل مطلوب':'راجعي السياق','tag'),el('p',i.message));$('issues').append(d)});$('record').textContent=JSON.stringify(report.record,null,2)}$('review').onclick=run;$('example').onclick=()=>{$('task').value='إرسال مسودة التقرير المالي للمراجعة';$('owner').value='مسؤولة التقرير';const d=new Date();d.setDate(d.getDate()+7);$('due').value=d.toLocaleDateString('en-CA');run()};$('export').onclick=()=>{run();download('action-review.json',report)};run();'''
(p/'actions/index.html').write_text(head('Action Review — Deema Alrafi')+actions+'<script>'+common+(p/'actions/engine.js').read_text()+ajs+'</script>'+foot)
